  function CharacterReforged.training_mode.int(v)
    if type(v) ~= "number" then
      return 0
    end
    return math.floor(v + 0.5)
  end

  function CharacterReforged.training_mode.signed(v)
    if v > 0 then
      return "+" .. v
    end
    return tostring(v)
  end

  -- menu_text row TX[key] with <VALUE>/<A> = a, <B> = b
  function CharacterReforged.training_mode.T(key, a, b)
    local T = CharacterReforged.training_mode
    local s = T.txt(T.TX[key])
    local map = {VALUE = a, A = a, B = b}
    return (string.gsub(s, "<(%u+)>", function(k)
      local v = map[k]
      if v == nil then
        return nil
      end
      return tostring(v)
    end))
  end

  function CharacterReforged.training_mode.stat_of(k)
    return CharacterReforged.training_mode.MAP[k] or k
  end

  function CharacterReforged.training_mode.row_of(i)
    local T = CharacterReforged.training_mode
    for k = T.FIRST, T.FIRST + T.ROWS - 1 do
      if T.MAP[k] == i then
        return k
      end
    end
    return T.FIRST
  end

  -- the short name of a position code ("" when unknown)
  function CharacterReforged.training_mode.pos_name(p)
    local key = CharacterReforged.training_mode.POS_KEY[p]
    return key ~= nil and CharacterReforged.training_mode.T(key) or ""
  end

  function CharacterReforged.training_mode.stat_name(i)
    return CharacterReforged.training_mode.txt(CharacterReforged.training_mode.TX.STATS[i + 1])
  end

