  -- the mode's layers are in the setting (training_ui_build.py deployed)
  function CharacterReforged.training_mode.mode_layers_exist()
    local T = CharacterReforged.training_mode
    for _, L in ipairs({T.L_PANEL, T.L_ROW, T.L_GAUGE, T.L_CELL}) do
      local ok, e = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], L)
      if not ok or e ~= true then
        return false
      end
    end
    return true
  end

  function CharacterReforged.training_mode.loader_ready()
    local T = CharacterReforged.training_mode
    local api = VRFW.host.command(T.CMD.VERSION)
    return type(api) == "number"
  end

  function CharacterReforged.training_mode.read_info()
    local T = CharacterReforged.training_mode
    local ok, status, total, avail, level, pos, dirty, _, rule = VRFW.host.command(T.CMD.INFO, T.hdl, 0)
    -- Rule 1 means pool.
    T.info = {ok = ok == true, status = T.int(status), total = T.int(total), avail = T.int(avail), level = T.int(level),
      pos = T.int(pos), dirty = dirty == true, pool = T.int(rule) == 1, rule = T.int(rule)}
    T.read_positions()
  end

  function CharacterReforged.training_mode.read_positions()
    local T = CharacterReforged.training_mode
    local ok, chosen, main, sub, trained, following, previous
    if T.info.ok then
      ok, chosen, main, sub, trained, following, previous = VRFW.host.command(T.CMD.POSITION, T.hdl)
    end
    T.pos = {ok = ok == true, chosen = T.int(chosen), main = T.int(main), sub = T.int(sub), trained = trained == true,
      following = T.int(following), previous = T.int(previous)}
    T.pos.switchable = T.pos.ok and T.pos.following ~= 0 and T.pos.following ~= T.pos.chosen
  end

  function CharacterReforged.training_mode.partner(i)
    local T = CharacterReforged.training_mode
    local s = T.st[i]
    if T.info.pool or s == nil then
      return nil
    end
    local best = nil
    for _, p in ipairs({s.p1, s.p2}) do
      local q = p ~= nil and p >= 0 and T.st[p] or nil
      if q ~= nil and (best == nil or T.ev(q) > T.ev(T.st[best])) then
        best = p
      end
    end
    return best
  end

  function CharacterReforged.training_mode.read_stats()
    local T = CharacterReforged.training_mode
    T.st = {}
    for i = 0, T.STAT_SLOTS - 1 do                 -- every stat slot (the retired one has no counterpart: never shown)
      local ok, v, b, bo, d, cd, mn, mx, p1, p2 = VRFW.host.command(T.CMD.STAT, T.hdl, i)
      if ok == true then
        T.st[i] = {value = T.int(v), base = T.int(b), bonus = T.int(bo), delta = T.int(d), committed = T.int(cd),
          min = T.int(mn), max = T.int(mx), p1 = T.int(p1), p2 = T.int(p2)}
      else
        T.st[i] = {value = 0, base = 0, bonus = 0, delta = 0, committed = 0, min = 0, max = 0, p1 = -1, p2 = -1}
      end
    end
    T.build_map()
  end

  -- Maps row instances to stat slots from the loader's answers.
  function CharacterReforged.training_mode.build_map()
    local T = CharacterReforged.training_mode
    local map, k = {}, T.FIRST
    for i = 0, T.STAT_SLOTS - 1 do
      local s = T.st[i]
      if s ~= nil and (s.p1 >= 0 or s.p2 >= 0) then
        map[k] = i
        k = k + 1
      end
    end
    if k == T.FIRST + T.ROWS then
      T.MAP = map
    end
  end

  -- Returns the value shown and edited.
  function CharacterReforged.training_mode.ev(s)
    return s.base + s.delta
  end

  function CharacterReforged.training_mode.ev_saved(s)
    return s.base + s.committed
  end

  function CharacterReforged.training_mode.refresh(reset_scale)
    local T = CharacterReforged.training_mode
    T.read_info()
    if T.info.ok then
      T.read_stats()
    end
    T.redraw(reset_scale)
  end

  function CharacterReforged.training_mode.load(fresh)
    local T = CharacterReforged.training_mode
    T.hdl = n
    T.hint = nil
    local ok, nm = pcall(funcLuaCommand, 1915015278 --[[CMND_GET_CHARA_NAME_TEXT]], T.hdl)
    T.name = (ok and type(nm) == "string") and nm or ""
    VRFW.host.command(T.CMD.INFO, T.hdl, fresh and 1 or 0)
    T.read_info()
    T.st = {}
    if T.info.ok then
      T.read_stats()
    end
    T.log("player", tostring(T.hdl), "ok", tostring(T.info.ok), "status", T.info.status, "free", T.info.avail, "of",
      T.info.total, "pool", tostring(T.info.pool))
  end

  function CharacterReforged.training_mode.cover(on)
    local T = CharacterReforged.training_mode
    local items = {}
    for r = 0, ROW_NUM - 1 do
      items[#items + 1] = {L_ROW, r}
    end
    items[#items + 1] = {L_CURSOR, 0}
    for _, L in ipairs({L_BTN, L_BTN_SS, PL.L_BTN_ROLE, T.L_BTN}) do
      items[#items + 1] = {L, 0}
    end
    for _, k in ipairs({ROW_ICON_SKILL_SLOT, PL.ROW_ICON_ROLE, ROW_ICON_PREVIEW}) do   -- PV: the player-sets save icon
      items[#items + 1] = {L_PV_ROW, k}
    end
    if on then
      T.covered = {}
      for _, it in ipairs(items) do
        local ok, v = pcall(funcLuaMenuCommand, 1262717583 --[[CMND_IS_LAYER_VISIBLE]], it[1], it[2])
        T.covered[#T.covered + 1] = {it[1], it[2], not ok or v ~= false}
        funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], false)
      end
    elseif T.covered ~= nil then
      for _, it in ipairs(T.covered) do
        funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], it[3])
      end
      T.covered = nil
    end
  end

  -- Redraws the rows after a player change.
  function CharacterReforged.training_mode.recover()
    local T = CharacterReforged.training_mode
    for _, it in ipairs(T.covered or {}) do
      funcLuaMenuCommand(C.LAYER_VISIBLE, it[1], it[2], false)
    end
  end

  function CharacterReforged.training_mode.open_all()
    local T = CharacterReforged.training_mode
    PL.open(T.L_PANEL, 0)
    for _, L in ipairs({T.L_ROW, T.L_GAUGE, T.L_CELL, T.L_ARROW, T.L_KEYS}) do
      for k = 0, T.COUNT[L] - 1 do
        PL.open(L, k)                              -- a layer missing from the setting is skipped
      end
    end
  end

  function CharacterReforged.training_mode.hide_all()
    local T = CharacterReforged.training_mode
    for L, cnt in pairs(T.COUNT) do
      for k = 0, cnt - 1 do
        pcall(funcLuaMenuCommand, C.LAYER_VISIBLE, L, k, false)   -- the optional layers may be missing
      end
    end
  end

  function CharacterReforged.training_mode.is_partner(i)
    local T = CharacterReforged.training_mode
    if T.info.pool then
      return false
    end
    local s = T.st[T.sel]
    return s ~= nil and (s.p1 == i or s.p2 == i)
  end

  function CharacterReforged.training_mode.row_alpha(i)
    local T = CharacterReforged.training_mode
    if T.info.pool or T.sel == T.SEL_POS or i == T.sel or T.is_partner(i) then
      return 1.0
    end
    return T.DIM
  end

  -- Draws a retail equipment plate.
  function CharacterReforged.training_mode.draw_row(k)
    local T = CharacterReforged.training_mode
    local L = T.L_ROW
    local i = T.stat_of(k)
    for _, pos in ipairs(T.POS_LIST) do
      funcLuaMenuCommand(POSITION_VISIBLE, L, pos, pos == T.POS_LIST[1], k)
    end
    for _, m in ipairs(T.M_ROW_HIDE) do
      funcLuaMenuCommand(C.MESH_VISIBLE, L, m, false, k)
    end
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.M_FOCUS, i == T.sel, k)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.ROWBAR.PLATE, T.ROWBAR.PLATE_ON, k)   -- the row's card: the name
    funcLuaMenuCommand(2575768773 --[[node pos]], L, k, T.ROWBAR.PLATE, 0, T.ROWBAR.PLATE_X)
    funcLuaMenuCommand(2885415772 --[[node scale]], L, k, T.ROWBAR.PLATE, T.ROWBAR.PLATE_W, T.ROWBAR.PLATE_H)
    funcLuaMenuCommand(2333948100 --[[text style]], L, k, T.T_ITEM, T.ST_ITEM)
    funcLuaMenuCommand(C.TEXT, L, T.T_ITEM, T.stat_name(i), k)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], L, k, 0, T.row_alpha(i))
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- the number of characters of a UTF-8 text (continuation bytes 128..191 not counted)
  function CharacterReforged.training_mode.char_count(text)
    local n = 0
    for k = 1, #text do
      local b = string.byte(text, k)
      if b < 128 or b >= 192 then
        n = n + 1
      end
    end
    return n
  end

  -- the engine's width of `text` in the position row's text node (row units), nil = no answer
  function CharacterReforged.training_mode.pos_text_width(text)
    local T = CharacterReforged.training_mode
    local ok, w = pcall(funcLuaMenuCommand, T.POSROW.RECT, T.L_ROW, T.POS_ROW, T.T_ITEM, text)
    w = ok and tonumber(w) or nil
    return (w ~= nil and w > 0) and w or nil
  end

  -- Returns the game's position badge sprite of position code p (1 GK, 2 FW, 3 MF, 4 DF), the one the screen's header uses.
  function CharacterReforged.training_mode.pos_sprite(p)
    local types = type(VRFW.chara_icons) == "table" and VRFW.chara_icons.ICON_TYPE or nil
    local t = types ~= nil and types[p] or nil
    if t == nil or type(GetSoccerCharaPositionIconByPosIconType) ~= "function" then
      return nil
    end
    local ok, sprite = pcall(GetSoccerCharaPositionIconByPosIconType, t)
    return (ok and type(sprite) == "number" and sprite ~= 0) and sprite or nil
  end

  function CharacterReforged.training_mode.draw_pos_row()
    local T, P = CharacterReforged.training_mode, CharacterReforged.training_mode.POSROW
    local L, k = T.L_ROW, T.POS_ROW
    if not (T.info and T.info.ok and T.pos and T.pos.ok) then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, false)
      return
    end
    for _, pos in ipairs(T.POS_LIST) do
      funcLuaMenuCommand(POSITION_VISIBLE, L, pos, pos == T.POS_LIST[1], k)
    end
    for _, m in ipairs(T.M_ROW_HIDE) do
      funcLuaMenuCommand(C.MESH_VISIBLE, L, m, false, k)
    end
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.M_FOCUS, false, k)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.ROWBAR.PLATE, false, k)
    funcLuaMenuCommand(2333948100 --[[text style]], L, k, T.T_ITEM, T.ST_ITEM)
    local sprite = T.pos_sprite(T.pos.chosen)
    local label = T.T("POS_LABEL")
    local w1, w2 = T.pos_text_width("x x"), T.pos_text_width("xx")
    local sw = (w1 ~= nil and w2 ~= nil and w1 > w2) and (w1 - w2) or P.SPACE_W
    local function width(text)
      return T.pos_text_width(text) or P.CHAR_W * T.char_count(text)
    end
    -- Pads the text for the badge's gap.
    local gap_text = sprite ~= nil and string.rep(" ", math.ceil((P.ICON_W + 2 * P.ICON_PAD) / sw))
      or (" " .. T.pos_name(T.pos.chosen) .. " ")
    local gap_w = sprite ~= nil and #gap_text * sw or width(gap_text)
    local line, area = label .. " ", width(label) + sw
    if T.pos.switchable then
      line, area = line .. P.ARROW_L, area + width(P.ARROW_L)
    end
    line = line .. gap_text
    local total = area + gap_w
    if T.pos.switchable then
      line, total = line .. P.ARROW_R, total + width(P.ARROW_R)
    end
    local lead = math.max(0, math.floor((P.CENTER_X - P.TEXT_X - total / 2) / sw + 0.5))
    local x0 = P.TEXT_X + lead * sw
    T.pos.line_l, T.pos.line_r = x0, x0 + total
    local measure = string.format("label %s space %s total %s lead %d badge %s", tostring(T.pos_text_width(label)),
      tostring(w1 ~= nil and w2 ~= nil and w1 - w2 or nil), tostring(total), lead, tostring(sprite))
    if measure ~= T.pos_measure then                 -- logged when it changes
      T.pos_measure = measure
      T.log("position row", measure, "switchable", tostring(T.pos.switchable))
    end
    funcLuaMenuCommand(C.TEXT, L, T.T_ITEM, string.rep(" ", lead) .. line, k)
    if sprite ~= nil then
      funcLuaMenuCommand(C.SPRITE, L, P.ICON_TEX, sprite, P.ICON_SLOT, 0, k)
      funcLuaMenuCommand(2575768773 --[[node pos]], L, k, P.ICON_MESH, 0, x0 + area + (gap_w - P.ICON_W) / 2)
      funcLuaMenuCommand(2575768773, L, k, P.ICON_MESH, 1, P.LINE_DY + P.ICON_H / 2)
      funcLuaMenuCommand(2885415772 --[[node scale]], L, k, P.ICON_MESH, P.ICON_W, P.ICON_H)
      funcLuaMenuCommand(C.MESH_VISIBLE, L, P.ICON_MESH, true, k)
    end
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], L, k, 0, T.sel == T.SEL_POS and 1.0 or P.DIM_ALPHA)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- Draws the keys of the focused position row.
  function CharacterReforged.training_mode.draw_pos_keys()
    local T, K, P = CharacterReforged.training_mode, CharacterReforged.training_mode.KEYS, CharacterReforged.training_mode.POSROW
    local L = T.L_KEYS
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L) ~= true then
      return
    end
    local ok, gx, gy = pcall(funcLuaMenuCommand, 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]], T.L_GAUGE, T.POS_ROW,
      K.BASE)
    local show = ok and type(gx) == "number" and type(gy) == "number" and T.info.ok and T.pos.switchable
    local row_x = show and gx - T.ROWBAR.GAUGE_X0 or 0  -- the row's origin (the gauge origin sits at row x GAUGE_X0)
    for j = 0, 1 do
      if (T.ready[L] or {})[j] then
        if show then
          local okg, glyph = pcall(funcLuaCommand, 4074371074 --[[CMND_TEXT_GET]], j == 0 and T.I_LEFT or T.I_RIGHT)
          funcLuaMenuCommand(1083631230 --[[CMND_SET_MENU_TEXT_STRING]], L, K.TEXT,
            okg and type(glyph) == "string" and glyph or "", j)
          funcLuaMenuCommand(1595998683 --[[rate]], L, K.RATE, 0, 0, j)
          funcLuaMenuCommand(3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], L, K.SCALE, K.SCALE, 1, j)
          funcLuaMenuCommand(1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], L,
            row_x + (j == 0 and (T.pos.line_l or 0) - P.KEY_GAP or (T.pos.line_r or 0) + P.KEY_GAP), gy + P.LINE_DY, 0, j)
        end
        funcLuaMenuCommand(C.LAYER_VISIBLE, L, j, show == true)
      end
    end
  end

  function CharacterReforged.training_mode.pointer_on_pos_row()
    local T = CharacterReforged.training_mode
    local okp, mx, my = pcall(funcLuaMenuCommand, T.POINTER)
    local okg, gx, gy = pcall(funcLuaMenuCommand, 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]], T.L_GAUGE, T.POS_ROW,
      T.KEYS.BASE)
    if not (okp and okg and type(mx) == "number" and type(my) == "number" and type(gx) == "number"
      and type(gy) == "number") then
      return false
    end
    local cx = gx - T.ROWBAR.GAUGE_X0
    return math.abs(mx - cx) <= T.POSROW.HALF_W and math.abs(-my - gy) <= T.POSROW.HALF_H
  end

  -- Computes the bar scale.
  function CharacterReforged.training_mode.update_scale(reset)
    local T = CharacterReforged.training_mode
    local m = 0
    for i = 0, 8 do
      local s = T.st[i]
      if s then
        m = math.max(m, T.ev(s), T.ev_saved(s))
      end
    end
    local want = math.max(100, math.ceil(m * 1.15 / 50) * 50)
    if reset or T.scale == nil or want > T.scale then
      T.scale = want
    end
  end

  function CharacterReforged.training_mode.set_prim(k, prim, value, visible)
    local L = CharacterReforged.training_mode.L_GAUGE
    local p = funcLuaMenuCommand(1927054058 --[[CMND_SEARCH_PRIM_INDEX]], L, k, prim)
    if p ~= nil then
      funcLuaMenuCommand(3609943765 --[[prim value]], L, k, p, value, true)
    end
    funcLuaMenuCommand(1233047821 --[[prim visible]], L, k, prim, visible)
  end

  -- Returns the dark copy of a retail stat icon (sprite crc of MENU_DEF.GetStatusParamIconName).
  function CharacterReforged.training_mode.dark_icon(icon)
    local T = CharacterReforged.training_mode
    if T.darkIcons == nil then
      T.darkIcons = {}
      if type(CALC_CRC) == "function" then
        for n = 1, T.RETAIL_ICONS do
          local name = string.format("icon_parameter%02d", n)
          T.darkIcons[CALC_CRC(name)] = CALC_CRC(T.DARK_ICON_PREFIX .. name)
        end
      end
    end
    return T.darkIcons[icon] or icon
  end

  -- Draws the column backing (spare gauge instance ROWS).
  function CharacterReforged.training_mode.draw_back()
    local T = CharacterReforged.training_mode
    local L, k, B = T.L_GAUGE, T.BACK_K, T.ROWBAR
    if not (T.ready[L] or {})[k] then
      return
    end
    local last = T.COUNT[L] - 1
    local gp = 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]]
    local ok0, _, y0 = pcall(funcLuaMenuCommand, gp, L, 0, T.KEYS.BASE)
    local ok1, _, y1 = pcall(funcLuaMenuCommand, gp, L, last, T.KEYS.BASE)
    if not (T.info.ok and ok0 and ok1 and type(y0) == "number" and type(y1) == "number" and y0 ~= y1) then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, false)
      return
    end
    local gk = B.GAUGE_K
    local pitch = math.abs(y0 - y1) / last / gk                  -- gauge units between two rows
    local h = B.PLATE_H / gk
    funcLuaMenuCommand(C.MESH_VISIBLE, L, T.M_ICON, false, k)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, B.SLASH, false, k)
    for _, p in ipairs({T.P_NUM_CUR, T.P_NUM_NEXT, T.P_NUM_MAX}) do
      T.set_prim(k, p, 0, false)
    end
    funcLuaMenuCommand(2575768773 --[[node pos]], L, k, B.NODE, 0, -5000)   -- the bar parked off screen
    funcLuaMenuCommand(C.MESH_VISIBLE, L, B.PILL, true, k)
    funcLuaMenuCommand(2575768773, L, k, B.PILL, 0, (B.BACK.X0 - B.GAUGE_X0) / gk)
    funcLuaMenuCommand(2575768773, L, k, B.PILL, 1, (k - T.FIRST) * pitch + h / 2)   -- the first stat row's top
    funcLuaMenuCommand(2885415772 --[[node scale]], L, k, B.PILL, (B.BACK.X1 - B.BACK.X0) / gk, (T.ROWS - 1) * pitch + h)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], L, k, 0, 1.0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  function CharacterReforged.training_mode.set_gauge_icon(k, i)
    local T = CharacterReforged.training_mode
    T.gauge_icon = T.gauge_icon or {}
    if T.gauge_icon[k] == i then
      return
    end
    T.gauge_icon[k] = i
    local ok, icon = false, 0
    if i < T.RETAIL_ICONS then
      ok, icon = pcall(MENU_DEF.GetStatusParamIconName, i)
    end
    if ok and type(icon) == "number" and icon ~= 0 then
      funcLuaMenuCommand(C.SPRITE, T.L_GAUGE, T.ICON_TEX, T.dark_icon(icon), T.ICON_NODE, 0, k)
      funcLuaMenuCommand(C.MESH_VISIBLE, T.L_GAUGE, T.M_ICON, true, k)
    else
      funcLuaMenuCommand(C.MESH_VISIBLE, T.L_GAUGE, T.M_ICON, false, k)
    end
  end

  function CharacterReforged.training_mode.draw_gauge(k)
    local T = CharacterReforged.training_mode
    if k == T.BACK_K then
      return T.draw_back()
    end
    local i = T.stat_of(k)
    local s = T.st[i]
    if not (T.ready[T.L_GAUGE] or {})[k] then
      return
    end
    if s == nil or not T.info.ok then
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_GAUGE, k, false)
      return
    end
    local v, old, top = T.ev(s), T.ev_saved(s), s.base + s.max
    T.set_prim(k, T.P_NUM_CUR, math.max(0, v), v <= old)
    T.set_prim(k, T.P_NUM_NEXT, math.max(0, v), v > old)
    T.set_prim(k, T.P_NUM_MAX, math.max(0, top), true)
    local r = math.max(0, math.min(1, v / T.scale))
    local r_old = math.max(0, math.min(1, old / T.scale))
    funcLuaMenuCommand(1595998683 --[[rate set]], T.L_GAUGE, T.R_GAUGE, 0, r, k, false, T.G_BAR)
    funcLuaMenuCommand(1595998683 --[[rate set]], T.L_GAUGE, T.R_GAUGE_RED, 0, math.max(r, r_old), k, false, T.G_BAR)
    pcall(funcLuaMenuCommand, 4231609516 --[[model alpha]], T.L_GAUGE, k, 0, T.row_alpha(i))
    T.set_gauge_icon(k, i)
    local B = T.ROWBAR
    funcLuaMenuCommand(C.MESH_VISIBLE, T.L_GAUGE, B.PILL, B.PILL_ON, k)   -- no navy capsule per row
    funcLuaMenuCommand(2575768773 --[[node pos]], T.L_GAUGE, k, B.NODE, 0, B.X)
    funcLuaMenuCommand(2575768773, T.L_GAUGE, k, B.NODE, 1, B.Y)
    funcLuaMenuCommand(2885415772 --[[node scale]], T.L_GAUGE, k, B.NODE, B.SX, B.SY)
    for _, m in ipairs(B.MOVE) do                  -- icon left of the name, the numbers above the bar
      funcLuaMenuCommand(2575768773, T.L_GAUGE, k, m[1], 0, m[2])
      funcLuaMenuCommand(2575768773, T.L_GAUGE, k, m[1], 1, m[3])
    end
    funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_GAUGE, k, true)
    if i == T.sel then
      pcall(T.draw_keys, k)
    end
  end

  function CharacterReforged.training_mode.draw_keys(k)
    local T, K = CharacterReforged.training_mode, CharacterReforged.training_mode.KEYS
    local L = T.L_KEYS
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L) ~= true then
      return
    end
    local gp = 499270986 --[[CMND_GET_MESH_GLOBAL_POSITION]]
    local ok1, ix, iy = pcall(funcLuaMenuCommand, gp, T.L_GAUGE, k, K.BASE)
    if not (ok1 and type(ix) == "number" and type(iy) == "number") then
      return
    end
    local at = {[0] = {ix + K.L_DX, iy + K.DY, T.I_LEFT}, {ix + K.R_DX, iy + K.DY, T.I_RIGHT}}
    for j = 0, 1 do
      if (T.ready[L] or {})[j] then
        local okg, glyph = pcall(funcLuaCommand, 4074371074 --[[CMND_TEXT_GET]], at[j][3])
        funcLuaMenuCommand(1083631230 --[[CMND_SET_MENU_TEXT_STRING]], L, K.TEXT,
          okg and type(glyph) == "string" and glyph or "", j)
        funcLuaMenuCommand(1595998683 --[[rate]], L, K.RATE, 0, 0, j)
        funcLuaMenuCommand(3778714801 --[[CMND_SET_LAYER_LOCAL_SCALE]], L, K.SCALE, K.SCALE, 1, j)
        funcLuaMenuCommand(1389957207 --[[CMND_SET_LAYER_LOCAL_POS]], L, at[j][1], at[j][2], 0, j)
        funcLuaMenuCommand(C.LAYER_VISIBLE, L, j, T.info.ok == true)
      end
    end
    if not K.logged then
      K.logged = true
      T.log("keys", "row", k, "gauge origin", ix, iy)
    end
  end

  function CharacterReforged.training_mode.arrow_ready()
    local ok, e = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], CharacterReforged.training_mode.L_ARROW)
    return ok and e == true
  end

  function CharacterReforged.training_mode.arrow_want()
    local T = CharacterReforged.training_mode
    local want = {}
    if not T.on or T.info == nil or not T.info.ok or T.st == nil or T.st[T.sel] == nil then
      return want
    end
    want[T.row_of(T.sel)] = true
    local p = T.partner(T.sel)
    if p ~= nil and T.MAP[T.row_of(p)] == p then  -- a shown stat (never the retired slot 7)
      want[T.ARROW.ROWS + T.row_of(p)] = true
    end
    return want
  end

  function CharacterReforged.training_mode.draw_arrow(i, want)
    local T, A = CharacterReforged.training_mode, CharacterReforged.training_mode.ARROW
    local L = T.L_ARROW
    if not (T.ready[L] or {})[i] then
      return
    end
    if not (want or T.arrow_want())[i] then
      funcLuaMenuCommand(C.LAYER_VISIBLE, L, i, false)
      return
    end
    local up = i < A.ROWS
    pcall(funcLuaMenuCommand, 551395392 --[[number prims visible]], L, i, false)
    for _, p in ipairs(A.PRIMS) do
      pcall(funcLuaMenuCommand, 1233047821 --[[prim visible]], L, i, p, false)
    end
    funcLuaMenuCommand(POSITION_VISIBLE, L, A.NUM, false, i)
    for _, s in ipairs(A.SIDES) do
      funcLuaMenuCommand(POSITION_VISIBLE, L, s, false, i)
    end
    funcLuaMenuCommand(POSITION_VISIBLE, L, up and A.UP or A.DOWN, true, i)
    local spr = up and A.SPR_UP or A.SPR_DOWN
    funcLuaMenuCommand(C.SPRITE, L, A.TEX, spr[1], spr[2], 0, i)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, i, true)
  end

  function CharacterReforged.training_mode.draw_arrows()
    local T = CharacterReforged.training_mode
    if not T.arrow_ready() then
      return
    end
    local want = T.arrow_want()
    for i = 0, T.COUNT[T.L_ARROW] - 1 do
      T.draw_arrow(i, want)
    end
  end

  function CharacterReforged.training_mode.cell(L, k, label, value)
    funcLuaMenuCommand(C.TEXT, L, CharacterReforged.training_mode.T_LABEL, label, k)
    funcLuaMenuCommand(C.TEXT, L, CharacterReforged.training_mode.T_VALUE, value, k)
    funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, true)
  end

  -- Draws the right panel.
  function CharacterReforged.training_mode.draw_panel()
    local T = CharacterReforged.training_mode
    local i = T.sel
    if i == T.SEL_POS then
      return T.draw_pos_panel()
    end
    local icon = i < T.RETAIL_ICONS and MENU_DEF.GetStatusParamIconName(i) or 0
    pcall(PL.panel_plain, 5, T.stat_name(i), "", icon ~= 0 and function(L)
      funcLuaMenuCommand(C.SPRITE, L, T.ICON_TEX, icon, PL.SLOT_AREA, 0, 0)
    end or nil)
    PL.hiper_wide = false
    -- Shows the focused stat's name on the purple bar (PanelPlain leaves it hidden).
    funcLuaMenuCommand(2735666188 --[[text visible]], L_DETAIL, 1704438437 --[[_text_name01]], true, 0)
    PL.type_tag_off()
    pcall(CharacterReforged.skill_table_detail_graph_sync)
    local s = T.st[i]
    if not T.info.ok or s == nil then
      for k = 0, T.COUNT[T.L_CELL] - 1 do
        funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_CELL, k, false)
      end
      T.hook_detail_layout()                         -- the panel keeps the training view's card (no cells, message state)
      pcall(PL.set_detail_layout, "training")
      return
    end
    -- VALOR BASE = the focused stat's untrained base (the floor for lowering by hand)
    T.cell(T.L_CELL, 0, T.T("C_LIB"), tostring(math.max(0, T.info.avail)))
    T.cell(T.L_CELL, 1, T.T("C_VALUE"), tostring(s.base))
    T.hook_detail_layout()
    pcall(PL.set_detail_layout, "training")         -- the stat banner / cells inside the one white card
  end

  function CharacterReforged.training_mode.draw_pos_panel()
    local T = CharacterReforged.training_mode
    local title = string.gsub(T.T("POS_LABEL"), "[:%s]+$", "")
    pcall(PL.panel_plain, 5, title, "", nil)
    PL.hiper_wide = false
    funcLuaMenuCommand(2735666188 --[[text visible]], L_DETAIL, 1704438437 --[[_text_name01]], true, 0)
    PL.type_tag_off()
    pcall(CharacterReforged.skill_table_detail_graph_sync)
    for k = 0, T.COUNT[T.L_CELL] - 1 do
      funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_CELL, k, false)
    end
    if T.info.ok then
      T.cell(T.L_CELL, 0, T.T("C_LIB"), tostring(math.max(0, T.info.avail)))
    end
    T.hook_detail_layout()
    pcall(PL.set_detail_layout, "training")
  end

  -- The training view's card, laid out from one rect (screen px of the 1920 x 1080 menu space, y down).
  CharacterReforged.training_mode.DETAIL = {
    CARD = {985, 640, 1920, 852},
    PAD = 12,                                      -- card left edge -> icon
    ICON = 64,                                     -- icon size
    GAP = 10,                                      -- icon -> name
    NAME_X = -261,
    BAND_Y = 188, BAND_H = 88, ICON_Y = 176,       -- layout units from the locator, y up
    BAND_INSET = 0,                                -- band right end inside the card
    LOCATOR = 1,                                   -- PL.LAYOUT_LOCS index of _pos_cr_detail01
    BAND_NODES = {1125548721 --[[_sp_base01]], 3384915402 --[[_wlv_base01]]},
    ICON_NODE = 2164615260,
    HIDE_MESH = {656425078 --[[_item_win_line01]], 3303013605 --[[_sp_win_base01]]},
    FLAVOR = 691026122,
  }

  -- Runs after the screen's own ApplyDetailLayout.
  function CharacterReforged.training_mode.apply_card()
    local T, D = CharacterReforged.training_mode, CharacterReforged.training_mode.DETAIL
    if not T.on or PL.layout_mode ~= "training" then
      return
    end
    local x0, x1 = D.CARD[1], D.CARD[3]
    local loc = PL.LAYOUT_LOCS[D.LOCATOR]
    local _, ly = PL.layout_loc(D.LOCATOR)
    local lx = x0 + D.PAD + D.ICON + D.GAP - D.NAME_X
    if loc ~= nil and funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L_BASE) then
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_BASE, 0, loc[1], 0, lx)
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_BASE, 0, loc[1], 1, ly)
    end
    if funcLuaMenuCommand(262659071 --[[CMND_IS_EXIST_LAYER]], L_DETAIL) then
      for _, node in ipairs(D.BAND_NODES) do
        funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, node, 0, x0 - lx)
        funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, node, 1, D.BAND_Y)
        funcLuaMenuCommand(2885415772 --[[node scale]], L_DETAIL, 0, node, x1 - x0 - D.BAND_INSET, D.BAND_H)
      end
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, D.ICON_NODE, 0, x0 + D.PAD - lx)
      funcLuaMenuCommand(PL.LAYOUT_NODE_POS, L_DETAIL, 0, D.ICON_NODE, 1, D.ICON_Y)
      funcLuaMenuCommand(2885415772 --[[node scale]], L_DETAIL, 0, D.ICON_NODE, D.ICON, D.ICON)
      for _, mesh in ipairs(D.HIDE_MESH) do         -- the description's divider line and window: no description here
        funcLuaMenuCommand(C.MESH_VISIBLE, L_DETAIL, mesh, false, 0)
      end
      funcLuaMenuCommand(2735666188 --[[text visible]], L_DETAIL, D.FLAVOR, false, 0)
    end
    if type(CharacterReforged.PLAYER_PAGE_HOST) == "table" then
      CharacterReforged.PLAYER_PAGE_HOST.card = D.CARD
    end
  end

  function CharacterReforged.training_mode.hook_detail_layout()
    local base = PL.apply_detail_layout
    if type(base) ~= "function" or PL.training_card_wrap == base then
      return
    end
    local wrapped = function(...)
      base(...)
      pcall(CharacterReforged.training_mode.apply_card)
    end
    PL.training_card_wrap = wrapped
    PL.apply_detail_layout = wrapped
  end

  -- Draws the screen's radar.
  function CharacterReforged.training_mode.draw_graph()
    local T = CharacterReforged.training_mode
    if not T.info.ok or UpdateCharaParameterGraphNextBeansByCharaStHdl == nil then
      return
    end
    local a4, a5 = {}, {}
    for t = 0, 7 do
      local s = T.st[t] or {base = 0, delta = 0, committed = 0}
      if t < 7 then
        local nob = T.int(funcLuaCommand(C.CHARA_GET, T.hdl, 14 + t, true, true))
        a4[t + 1] = T.ev_saved(s) - nob
        a5[t + 1] = T.ev(s) - nob
      else
        a4[t + 1] = 0
        a5[t + 1] = 0
      end
    end
    local ok, err = pcall(UpdateCharaParameterGraphNextBeansByCharaStHdl, T.GRAPH[1], T.GRAPH[2], T.hdl, a4, a5,
      T.GRAPH[3])
    if not ok then
      T.log("graph", tostring(err))
    end
  end

  function CharacterReforged.training_mode.draw_guide()
    local T = CharacterReforged.training_mode
    local line = T.hint
    if line == nil then
      if not T.info.ok then
        line = T.info.status == T.ERR_LOCKED and T.T("LOCKED") or T.T("NO_DATA")
      elseif T.sel == T.SEL_POS and T.pos.switchable then
        line = T.T("POS_GUIDE", T.pos_name(T.pos.chosen), T.pos_name(T.pos.following))
      elseif T.sel == T.SEL_POS then
        line = T.T("POS_SINGLE", T.pos_name(T.pos.chosen))
      else
        line = T.T("GUIDE_SHORT")
      end
    end
    PL.guide(line)
    local keys = {}
    if T.info.ok then
      keys = {{text = T.TX.G_SAVE, icon = PL.I_FUNC4, cmd = PL.K_FUNC4},
        {text = T.TX.G_RESET, icon = PL.I_FUNC1, cmd = PL.K_FUNC1}}
      if T.sel ~= T.SEL_POS then
        table.insert(keys, 1, {text = T.TX.G_ACCEPT, icon = PL.I_ENTER, cmd = PL.K_ENTER})
      end
    end
    keys[#keys + 1] = {text = T.TX.G_BACK, icon = PL.I_BACK, cmd = PL.K_BACK}
    pcall(PL.guide_keys, keys)
  end

  -- Puts the screen's arrow cursor on the focused row (on) or back on the screen (off).
  function CharacterReforged.training_mode.cursor(on)
    local T, U = CharacterReforged.training_mode, CharacterReforged.training_mode.CURSOR
    local count = T.COUNT[T.L_ROW]
    local at = nil
    if on then
      at = T.sel == T.SEL_POS and T.POS_ROW or T.row_of(T.sel)
      funcLuaMenuCommand(C.LAYER_VISIBLE, L_CURSOR, 0, true)
    end
    if at == T.cursor_at then
      return
    end
    if on and T.cursor_at == nil then
      local rows = (ROW_NUM or 0) + 1
      pcall(funcLuaMenuCommand, U.LOCATOR, L_ROW, U.LABEL, rows, rows)
    end
    T.cursor_at = at
    pcall(funcLuaMenuCommand, U.LOCATOR, T.L_ROW, U.LABEL, at or count, count)
    if not on then
      character_reforged_cursor_idx = -1
    end
  end

  function CharacterReforged.training_mode.redraw(reset_scale)
    local T = CharacterReforged.training_mode
    T.update_scale(reset_scale)
    PL.open(T.L_PANEL, 0)
    funcLuaMenuCommand(C.LAYER_VISIBLE, T.L_PANEL, 0, true)
    T.draw_pos_row()
    for k = T.FIRST, T.FIRST + T.ROWS - 1 do
      T.draw_row(k)
      T.draw_gauge(k)
    end
    if T.sel == T.SEL_POS then                       -- the key rings beside the position instead
      pcall(T.draw_pos_keys)
    end
    T.draw_back()                                     -- the column backing: gauge instance BACK_K
    T.draw_arrows()
    T.draw_panel()
    T.draw_graph()
    T.draw_guide()
    T.cursor(true)
  end

  function CharacterReforged.training_mode.commit()
    local T = CharacterReforged.training_mode
    if not T.info.ok or not T.info.dirty then
      return true
    end
    local ok, status = VRFW.host.command(T.CMD.COMMIT, T.hdl)
    T.log("commit", tostring(T.hdl), tostring(ok), tostring(status))
    if ok ~= true then
      VRFW.question.notice(T.T("SAVE_FAILED", T.int(status)))
      return false
    end
    return true
  end

  -- Aceptar (close = true) / Guardar (close = false)
  function CharacterReforged.training_mode.save(close)
    local T = CharacterReforged.training_mode
    local dirty = T.info.ok and T.info.dirty
    if not T.commit() then
      return false
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    if dirty and not T.saved_hint then
      T.saved_hint = true
      VRFW.question.notice(T.T("SAVED"))
    end
    if not close then
      T.hint = nil
      T.refresh(false)
      pcall(UpdateCharaStatus)
    end
    return true
  end

  function CharacterReforged.training_mode.back()
    local T = CharacterReforged.training_mode
    if T.info.ok and T.info.dirty then
      funcLuaCommand(C.SE, SE_OK)
      if not VRFW.question.ask(T.T("ASK_DISCARD")) then
        T.draw_guide()
        return false
      end
    end
    funcLuaCommand(C.SE, SE_BACK)
    return true
  end

  function CharacterReforged.training_mode.reset()
    local T = CharacterReforged.training_mode
    if not T.info.ok then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if VRFW.question.ask(T.T("ASK_RESET", T.name)) then
      VRFW.host.command(T.CMD.RESET, T.hdl)
      funcLuaCommand(C.SE, SE_OK)
    end
    T.hint = nil
    T.refresh(false)
  end

  -- Up / Down over the position row (instance POS_ROW) and the stat rows, wrapping around
  function CharacterReforged.training_mode.row(dir)
    local T = CharacterReforged.training_mode
    T.hint = nil
    local at = T.sel == T.SEL_POS and T.POS_ROW or T.row_of(T.sel)
    local k = (at - T.POS_ROW + dir) % (T.ROWS + 1) + T.POS_ROW
    T.sel = k == T.POS_ROW and T.SEL_POS or T.stat_of(k)
    funcLuaCommand(C.SE, 2500047763 --[[sy0005 cursor]])
    T.redraw(false)
  end

  -- Handles the position row's Left (dir < 0: the previous allowed position), Right, Aceptar and click.
  function CharacterReforged.training_mode.switch_position(dir)
    local T = CharacterReforged.training_mode
    T.hint = nil
    if not (T.info.ok and T.pos.switchable) then
      funcLuaCommand(C.SE, SE_NG)
      T.draw_guide()
      return
    end
    local target = (dir ~= nil and dir < 0) and T.pos.previous or T.pos.following
    if T.pos.trained then
      funcLuaCommand(C.SE, SE_OK)
      if not VRFW.question.ask(T.T("ASK_POSITION", T.name, T.pos_name(target))) then
        T.draw_guide()
        return
      end
    end
    local ok = VRFW.host.command(T.CMD.SET_POSITION, T.hdl, target)
    T.log("position", tostring(T.hdl), target, tostring(ok))
    funcLuaCommand(C.SE, ok == true and SE_DECIDE or SE_NG)
    T.refresh(false)
  end

  function CharacterReforged.training_mode.step(dir)
    local T = CharacterReforged.training_mode
    if T.sel == T.SEL_POS then
      return T.switch_position(dir)
    end
    if not T.info.ok then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if dir == T.lastDir and T.frame - T.lastFrame <= T.HOLD_GAP then
      T.rep = T.rep + 1
    else
      T.rep = 0
    end
    T.lastDir, T.lastFrame = dir, T.frame
    local amount = (T.step10 or T.rep >= T.HOLD_REPEATS) and 10 or 1
    local s = T.st[T.sel]
    local ok, stop, reached = VRFW.host.command(T.CMD.SET, T.hdl, T.sel, s.delta + dir * amount)
    if type(reached) ~= "number" or T.int(reached) == s.delta then
      funcLuaCommand(C.SE, SE_NG)
    else
      funcLuaCommand(C.SE, 2500047763 --[[sy0005 cursor]])
    end
    -- Records why it stopped (also after a partial 10-point step) for the guide line.
    T.hint = nil
    stop = T.int(stop)
    if ok ~= true and stop == 1 and T.info.pool then
      T.hint = T.T("EMPTY")
    elseif ok ~= true and stop == 1 then
      local pair = T.partner(T.sel)
      T.hint = T.T("NO_TRADE", T.stat_name(T.sel), pair ~= nil and T.stat_name(pair) or "-")
    elseif ok ~= true and (stop == 3 or (stop == 5 and not T.info.pool)) then
      T.hint = T.T("FLOOR_BASE", T.stat_name(T.sel), s.base)
    elseif ok ~= true and stop == 5 then
      T.hint = T.T("FLOOR", T.stat_name(T.sel), s.base + s.min)
    elseif ok ~= true and stop == 2 then
      T.hint = T.T("CAP", T.stat_name(T.sel), s.base + s.max)
    end
    T.refresh(false)
  end

  -- Handles L1 and R1.
  function CharacterReforged.training_mode.switch(dir)
    local T = CharacterReforged.training_mode
    if n15 == nil or n15 <= 1 then
      funcLuaCommand(C.SE, SE_NG)
      return
    end
    if T.info.ok and T.info.dirty then
      if VRFW.question.ask(T.T("ASK_SWITCH", T.name)) then
        if not T.commit() then
          T.draw_guide()
          return
        end
      else
        VRFW.host.command(T.CMD.CANCEL, T.hdl)
      end
    end
    funcLuaCommand(C.SE, 3791946501 --[[sy0004]])
    funcLuaMenuCommand(3781155141 --[[CMND_PLAY_ANIME_TYPE]], L_BASE, 0, dir < 0 and 1203080170 or 3183130249, 0,
      3627544126)
    for _ = 1, n15 do
      n5 = (n5 + dir) % n15
      n4 = GetCharaIndexBySortIndex(n5)
      if t4[n4 + 1] ~= 0 then
        break
      end
    end
    local ok, err = pcall(ChangeChara, n4)
    if not ok then
      T.log("ChangeChara", tostring(err))
    end
    T.recover()
    T.load(true)
    T.redraw(true)
  end

  function CharacterReforged.training_mode.mode()
    local T = CharacterReforged.training_mode
    funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, false)
    if not T.loader_ready() then
      funcLuaCommand(C.SE, SE_NG)
      VRFW.question.notice(T.T("NO_LOADER"))
      funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, true)
      return
    end
    funcLuaCommand(C.SE, SE_DECIDE)
    T.on = true
    T.sel, T.step10, T.hint = T.stat_of(T.FIRST), false, nil
    T.cursor_at, T.gauge_icon = nil, {}
    T.frame, T.lastDir, T.lastFrame, T.rep = 0, 0, -100, 0
    T.scale = nil
    pcall(CharacterReforged.skill_table_detail_hide)
    T.cover(true)
    T.open_all()
    T.load(true)
    T.log("mode on", tostring(T.hdl))
    local wait = 0                                 -- the gauges bind their bars in OnOpenLayer
    while wait < 30 do
      local all = true
      for k = T.FIRST, T.FIRST + T.ROWS - 1 do
        all = all and (T.ready[T.L_GAUGE] or {})[k] == true
      end
      if all then
        break
      end
      wait = wait + 1
      coroutine.yield()
    end
    T.redraw(true)
    coroutine.yield()                              -- the Aceptar that opened the mode must not count
    while true do
      coroutine.yield()
      T.frame = T.frame + 1
      local enter = PL.key(PL.K_ENTER)
      local click = PL.key(T.K_CLICK)
      if PL.key(COMMAND_BACK) then
        if T.back() then
          break
        end
      elseif click and not enter and T.info.ok and T.pointer_on_pos_row() then   -- a mouse click on the position row
        if T.sel ~= T.SEL_POS then
          T.sel = T.SEL_POS
          T.redraw(false)
        end
        T.switch_position()
      elseif T.sel == T.SEL_POS and (enter or click) then
        T.switch_position()
      elseif T.info.ok and (enter or click) then
        if T.save(true) then
          break
        end
      elseif T.info.ok and PL.key(PL.K_FUNC4) then
        T.save(false)
      elseif PL.key(PL.K_FUNC1) then
        T.reset()
      elseif PL.key(COMMAND_UP) then
        T.row(-1)
      elseif PL.key(COMMAND_DOWN) then
        T.row(1)
      elseif PL.key(T.K_LEFT) then
        T.step(-1)
      elseif PL.key(T.K_RIGHT) then
        T.step(1)
      elseif PL.key(T.K_L1) then
        T.switch(-1)
      elseif PL.key(T.K_R1) then
        T.switch(1)
      elseif PL.key(T.K_FUNC2) then
        T.hint = nil
        T.step10 = not T.step10
        funcLuaCommand(C.SE, SE_OK)
        T.draw_guide()
      end
    end
    T.exit()
  end

  function CharacterReforged.training_mode.exit()
    local T = CharacterReforged.training_mode
    VRFW.host.command(T.CMD.CANCEL, 0)                        -- drop every working copy (saved training stays)
    T.on = false
    T.hide_all()
    pcall(PL.detail_hide_all)
    T.cover(false)
    pcall(T.cursor, false)
    coroutine.yield()                              -- the closing input must not reach the screen
    pcall(RefreshRows)
    pcall(UpdateCharaStatus)                       -- player card (shown stats include the training)
    pcall(UpdateEquipItemInfo)                     -- radar, detail panel, button guide of the screen
    pcall(T.label)
    pcall(T.guide)
    funcLuaMenuCommand(C.MENU_ACTIVE, T.EVT_MENU, true)
    T.log("mode off", tostring(n))
  end

  function CharacterReforged.training_mode.coroutine()
    if CharacterReforged.training_mode.mode_layers_exist() then
      return CharacterReforged.training_mode.mode()
    end
    return CharacterReforged.training_mode.window_coroutine()
  end

  function CharacterReforged.training_skill_table_button(phase, ctx)
    local T = CharacterReforged.training_mode
    if phase == "guide" then
      return T.txt(T.TX_GUIDE)
    elseif phase == "press" then
      T.log("button pressed", tostring(ctx and ctx.chara))
      return T.coroutine()
    end
    return nil
  end

  -- Hooks the global.
  function CharacterReforged.training_mode.hook(point, handler)
    local T = CharacterReforged.training_mode
    if SkillTable.hosted and type(VRFW.host) == "table" and type(VRFW.host.on) == "function" then
      VRFW.host.on("vrfw_skill_slot_menu", point, {id = "CharacterReforged.training_mode", phase = "around", fn = handler})
      return
    end
    T.wrapped = T.wrapped or {}
    local previous = _ENV[point]
    if T.wrapped[point] or type(previous) ~= "function" then
      return
    end
    T.wrapped[point] = true
    _ENV[point] = function(...)
      return handler(previous, ...)
    end
  end

  -- Sets up the mode's layers.
  CharacterReforged.training_mode.hook("OnSetupLayer", function(next_handler, a1, a2, ...)
    local T = CharacterReforged.training_mode
    if T.COUNT[a1] ~= nil then
      local prio = T.PRIO[a1]
      if a1 == T.L_GAUGE and a2 == T.BACK_K then
        prio = T.ROWBAR.BACK.PRIO                  -- the column backing: under everything else
      end
      funcLuaMenuCommand(Priority, a1, a2, prio, true)
      funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
      return
    end
    return next_handler(a1, a2, ...)
  end)

  CharacterReforged.training_mode.hook("OnOpenLayer", function(next_handler, a1, a2, ...)
    local T = CharacterReforged.training_mode
    if T.COUNT[a1] ~= nil then
      if a1 == T.L_GAUGE and a2 == T.BACK_K then   -- the column backing: its sprite
        funcLuaMenuCommand(C.SPRITE, a1, T.ROWBAR.BACK_TEX, T.ROWBAR.BACK.SPRITE, T.ROWBAR.BACK_SLOT, 0, a2)
      end
      if a1 == T.L_GAUGE and a2 ~= nil and a2 ~= T.BACK_K then
        (T.gauge_icon or {})[a2] = nil             -- the open resets the layout: DrawGauge sets the stat icon again
        local g = funcLuaMenuCommand(112302847 --[[CMND_GET_GROUP_INDEX]], a1, a2, T.G_BAR)
        funcLuaMenuCommand(541357333 --[[rate bind]], a1, T.R_GAUGE, g, a2)
        funcLuaMenuCommand(541357333 --[[rate bind]], a1, T.R_GAUGE_RED, g, a2)
      end
      T.ready[a1] = T.ready[a1] or {}
      T.ready[a1][a2 or 0] = true
      if a1 == T.L_PEBAR then                      -- unused layer of the setting: kept hidden
        funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
      elseif not T.on then
        funcLuaMenuCommand(C.LAYER_VISIBLE, a1, a2, false)
      elseif a1 == T.L_GAUGE then
        pcall(T.draw_gauge, a2)
      elseif a1 == T.L_ROW and a2 == T.POS_ROW then
        pcall(T.draw_pos_row)
      elseif a1 == T.L_ROW then
        pcall(T.draw_row, a2)
      elseif a1 == T.L_ARROW then
        pcall(T.draw_arrow, a2)
      end
      return
    end
    return next_handler(a1, a2, ...)
  end)
  end
end
